enum VehicleType {
    MOTORCYCLE(1), CAR(2), TRUCK(3);
    final int size;                                   // smallest spot size that fits
    VehicleType(int size) { this.size = size; }
}

record Vehicle(String plate, VehicleType type) {}

record Ticket(String id, Vehicle vehicle, ParkingSpot spot, Instant entry) {}

class ParkingSpot {
    private final String id;
    private final int floor;
    private final int size;                           // 1 small, 2 medium, 3 large
    private Vehicle occupant;                         // guarded by this

    ParkingSpot(String id, int floor, int size) {
        this.id = id; this.floor = floor; this.size = size;
    }
    String id() { return id; }
    int floor() { return floor; }
    int size() { return size; }

    synchronized boolean tryPark(Vehicle v) {         // atomic check-and-set
        if (occupant != null || v.type().size > size) return false;
        occupant = v;
        return true;
    }
    synchronized void free() { occupant = null; }
    synchronized boolean isFree() { return occupant == null; }
}
interface SpotAllocationStrategy {
    Optional<ParkingSpot> allocate(List<ParkingSpot> spots, Vehicle v);
}

/** Lowest floor first, then the tightest fit, so large spots stay available for trucks. */
class NearestTightFit implements SpotAllocationStrategy {
    public Optional<ParkingSpot> allocate(List<ParkingSpot> spots, Vehicle v) {
        for (ParkingSpot s : spots.stream()
                .sorted((a, b) -> a.floor() != b.floor() ? a.floor() - b.floor()
                                                          : a.size() - b.size())
                .toList()) {
            if (s.tryPark(v)) return Optional.of(s);   // tryPark is the atomic claim
        }
        return Optional.empty();
    }
}

interface FeeStrategy { long feeInRupees(VehicleType type, Duration stay); }

class HourlyFee implements FeeStrategy {
    private static final Map<VehicleType, Long> RATE =
        Map.of(VehicleType.MOTORCYCLE, 10L, VehicleType.CAR, 30L, VehicleType.TRUCK, 60L);
    public long feeInRupees(VehicleType type, Duration stay) {
        long hours = Math.max(1, (stay.toMinutes() + 59) / 60);      // round up, minimum one hour
        return hours * RATE.get(type);
    }
}
class ParkingFullException extends RuntimeException {
    ParkingFullException(String m) { super(m); }
}

class ParkingLot {
    private final List<ParkingSpot> spots;
    private final SpotAllocationStrategy allocation;
    private final FeeStrategy fees;
    private final Supplier<Instant> clock;                          // injected for testing
    private final Map<String, Ticket> active = new ConcurrentHashMap<>();

    ParkingLot(List<ParkingSpot> spots, SpotAllocationStrategy a, FeeStrategy f,
               Supplier<Instant> clock) {
        this.spots = List.copyOf(spots); this.allocation = a; this.fees = f; this.clock = clock;
    }

    Ticket park(Vehicle v) {
        ParkingSpot spot = allocation.allocate(spots, v)
            .orElseThrow(() -> new ParkingFullException("no spot for " + v));
        Ticket t = new Ticket(UUID.randomUUID().toString().substring(0, 8), v, spot, clock.get());
        active.put(t.id(), t);
        return t;
    }

    long exit(String ticketId) {
        Ticket t = active.remove(ticketId);                 // atomic: no double exit
        if (t == null) throw new IllegalArgumentException("unknown or used ticket " + ticketId);
        t.spot().free();
        return fees.feeInRupees(t.vehicle().type(), Duration.between(t.entry(), clock.get()));
    }

    long freeSpots() { return spots.stream().filter(ParkingSpot::isFree).count(); }
}
public class ParkingLotDemo {
    public static void main(String[] args) throws Exception {
        List<ParkingSpot> spots = new ArrayList<>();
        for (int floor = 0; floor < 2; floor++) {
            spots.add(new ParkingSpot("F" + floor + "-S1", floor, 1));
            spots.add(new ParkingSpot("F" + floor + "-M1", floor, 2));
            spots.add(new ParkingSpot("F" + floor + "-M2", floor, 2));
            spots.add(new ParkingSpot("F" + floor + "-L1", floor, 3));
        }
        Instant[] now = {Instant.parse("2026-01-01T09:00:00Z")};     // controllable clock
        ParkingLot lot = new ParkingLot(spots, new NearestTightFit(), new HourlyFee(),
                                        () -> now[0]);

        Ticket bike = lot.park(new Vehicle("AP39-1111", VehicleType.MOTORCYCLE));
        Ticket car = lot.park(new Vehicle("AP39-2222", VehicleType.CAR));
        Ticket truck = lot.park(new Vehicle("AP39-3333", VehicleType.TRUCK));
        System.out.println("bike -> " + bike.spot().id() + ", car -> " + car.spot().id()
            + ", truck -> " + truck.spot().id() + ", free = " + lot.freeSpots());

        now[0] = now[0].plus(Duration.ofMinutes(150));
        System.out.println("car fee after 150 min = Rs " + lot.exit(car.id()));
        try { lot.exit(car.id()); } catch (IllegalArgumentException e) {
            System.out.println("second exit rejected: " + e.getMessage().substring(0, 23));
        }

        // concurrency check: 40 cars compete for the remaining medium-or-larger spots
        ExecutorService pool = Executors.newFixedThreadPool(8);
        AtomicInteger ok = new AtomicInteger(), full = new AtomicInteger();
        for (int i = 0; i < 40; i++) {
            final int n = i;
            pool.submit(() -> {
                try { lot.park(new Vehicle("CAR-" + n, VehicleType.CAR)); ok.incrementAndGet(); }
                catch (ParkingFullException e) { full.incrementAndGet(); }
            });
        }
        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);
        System.out.println("parked = " + ok + ", rejected = " + full
            + ", free = " + lot.freeSpots());
    }
}

import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.LongAdder;
import java.util.concurrent.locks.ReentrantLock;

interface Cache<K, V> {
    Optional<V> get(K key);
    void put(K key, V value);
    int size();
}
class LruCache<K, V> implements Cache<K, V> {
    private final class Node {
        final K key; V value; Node prev, next;
        Node(K key, V value) { this.key = key; this.value = value; }
    }
    private final int capacity;
    private final Map<K, Node> index = new HashMap<>();
    private final Node head = new Node(null, null);       // sentinel: most recently used side
    private final Node tail = new Node(null, null);       // sentinel: least recently used side
    private final ReentrantLock lock = new ReentrantLock();

    LruCache(int capacity) {
        if (capacity <= 0) throw new IllegalArgumentException("capacity");
        this.capacity = capacity;
        head.next = tail; tail.prev = head;
    }
    public Optional<V> get(K key) {
        lock.lock();                       // get mutates the recency list, so it needs the lock
        try {
            Node n = index.get(key);
            if (n == null) return Optional.empty();
            unlink(n); addFirst(n);
            return Optional.of(n.value);
        } finally { lock.unlock(); }
    }
    public void put(K key, V value) {
        lock.lock();
        try {
            Node n = index.get(key);
            if (n != null) { n.value = value; unlink(n); addFirst(n); return; }
            if (index.size() == capacity) {
                Node lru = tail.prev;
                unlink(lru); index.remove(lru.key);
            }
            n = new Node(key, value);
            index.put(key, n); addFirst(n);
        } finally { lock.unlock(); }
    }
    public int size() {
        lock.lock();
        try { return index.size(); } finally { lock.unlock(); }
    }
    private void unlink(Node n) { n.prev.next = n.next; n.next.prev = n.prev; }
    private void addFirst(Node n) {
        n.next = head.next; n.prev = head; head.next.prev = n; head.next = n;
    }
}
class LfuCache<K, V> implements Cache<K, V> {
    private final int capacity;
    private final Map<K, V> values = new HashMap<>();
    private final Map<K, Integer> freq = new HashMap<>();
    private final Map<Integer, LinkedHashSet<K>> buckets = new HashMap<>();   // freq -> keys
    private int minFreq = 0;

    LfuCache(int capacity) { this.capacity = capacity; }
    public synchronized Optional<V> get(K key) {
        if (!values.containsKey(key)) return Optional.empty();
        touch(key);
        return Optional.of(values.get(key));
    }
    public synchronized void put(K key, V value) {
        if (values.containsKey(key)) { values.put(key, value); touch(key); return; }
        if (values.size() == capacity) {                   // least frequent, oldest
            Iterator<K> it = buckets.get(minFreq).iterator();
            K victim = it.next();
            it.remove();
            values.remove(victim); freq.remove(victim);
        }
        values.put(key, value); freq.put(key, 1);
        buckets.computeIfAbsent(1, f -> new LinkedHashSet<>()).add(key);
        minFreq = 1;
    }
    public synchronized int size() { return values.size(); }

    private void touch(K key) {
        int f = freq.get(key);
        LinkedHashSet<K> set = buckets.get(f);
        set.remove(key);
        if (set.isEmpty() && minFreq == f) minFreq = f + 1;
        freq.put(key, f + 1);
        buckets.computeIfAbsent(f + 1, x -> new LinkedHashSet<>()).add(key);
    }
}
public class CacheDemo {
    static void scenario(String name, Cache<String, Integer> c) {
        c.put("a", 1); c.put("b", 2); c.put("c", 3);
        c.get("a"); c.get("a"); c.get("a"); c.get("b"); c.get("c");   // a: 4 uses, oldest
        c.put("d", 4);                                 // capacity 3: someone is evicted
        StringBuilder sb = new StringBuilder(name + " after put(d): ");
        for (String k : new String[] {"a", "b", "c", "d"})
            sb.append(k).append(c.get(k).isPresent() ? "=hit " : "=miss ");
        System.out.println(sb);
    }

    static void stress(String name, Cache<Integer, Integer> c) throws Exception {
        LongAdder hits = new LongAdder(), ops = new LongAdder();
        ExecutorService pool = Executors.newFixedThreadPool(4);
        for (int t = 0; t < 4; t++) {
            pool.submit(() -> {
                ThreadLocalRandom r = ThreadLocalRandom.current();
                for (int i = 0; i < 100_000; i++) {
                    int key = r.nextInt(10) < 8 ? r.nextInt(100) : r.nextInt(1000);   // 80/20 skew
                    if (c.get(key).isPresent()) hits.increment(); else c.put(key, key);
                    ops.increment();
                }
            });
        }
        pool.shutdown();
        pool.awaitTermination(30, TimeUnit.SECONDS);
        System.out.printf("%s: size=%d (capacity 200), hit ratio=%.2f%n", name, c.size(),
            hits.doubleValue() / ops.doubleValue());
    }

    public static void main(String[] args) throws Exception {
        scenario("LRU", new LruCache<>(3));
        scenario("LFU", new LfuCache<>(3));
        stress("LRU", new LruCache<>(200));
        stress("LFU", new LfuCache<>(200));
    }
}

