    void setState(ElevatorState s) { this.state = s; }
    void setHeading(Direction d) { this.heading = d; }
    void moveOne() { floor += (heading == Direction.UP) ? 1 : -1; }
    void arrive() { stops.remove(floor); }

    /** LOOK policy: keep going while there is work ahead, otherwise reverse or stop. */
    void decide() {
        boolean up = hasStopsAbove(), down = hasStopsBelow();
        if (heading == Direction.UP && up) setState(new MovingState());
        else if (heading == Direction.DOWN && down) setState(new MovingState());
        else if (up) { heading = Direction.UP; setState(new MovingState()); }
        else if (down) { heading = Direction.DOWN; setState(new MovingState()); }
        else { heading = Direction.IDLE; setState(new IdleState()); }
    }
}
class IdleState implements ElevatorState {
    public String name() { return "IDLE"; }
    public void step(Elevator e) {
        if (e.hasStopHere()) { e.arrive(); e.setState(new DoorOpenState()); }
        else if (e.hasStops()) e.decide();
    }
}

class MovingState implements ElevatorState {
    public String name() { return "MOVING"; }
    public void step(Elevator e) {
        e.moveOne();
        if (e.hasStopHere()) { e.arrive(); e.setState(new DoorOpenState()); }
    }
}

class DoorOpenState implements ElevatorState {
    public String name() { return "DOOR_OPEN"; }
    public void step(Elevator e) { e.decide(); }             // doors close, then choose next move
}
interface DispatchStrategy { Elevator choose(List<Elevator> cars, HallCall call); }

class NearestCarStrategy implements DispatchStrategy {
    public Elevator choose(List<Elevator> cars, HallCall call) {
        Elevator best = null;
        int bestCost = Integer.MAX_VALUE;
        for (Elevator e : cars) {
            int cost = Math.abs(e.floor() - call.floor());
            boolean idle = e.heading() == Direction.IDLE;
            boolean onTheWay = (e.heading() == Direction.UP && e.floor() <= call.floor()
                                    && call.direction() == Direction.UP)
                            || (e.heading() == Direction.DOWN && e.floor() >= call.floor()
                                    && call.direction() == Direction.DOWN);
            if (!idle && !onTheWay) cost += 100;               // moving away: heavy penalty
            if (cost < bestCost) { bestCost = cost; best = e; }
        }
        return best;
    }
}

class ElevatorController {
    private final List<Elevator> cars = new ArrayList<>();
    private final DispatchStrategy strategy;
    ElevatorController(int count, DispatchStrategy s) {
        for (int i = 0; i < count; i++) cars.add(new Elevator(i, 0));
        this.strategy = s;
    }
    List<Elevator> cars() { return cars; }
    Elevator request(HallCall call) {
        Elevator e = strategy.choose(cars, call);
        e.addStop(call.floor());
        return e;
    }
    void press(int carId, int floor) { cars.get(carId).addStop(floor); }
    void tick() { cars.forEach(Elevator::step); }
}
public class ElevatorDemo {
    public static void main(String[] args) {
        ElevatorController ctl = new ElevatorController(2, new NearestCarStrategy());
        ctl.cars().get(1).addStop(8);                       // car 1 is sent to floor 8 first
        Map<Integer, Runnable> script = new TreeMap<>();
        script.put(1, () -> System.out.println("   call UP at 3 -> car "
            + ctl.request(new HallCall(3, Direction.UP)).id));
        script.put(2, () -> System.out.println("   call DOWN at 6 -> car "
            + ctl.request(new HallCall(6, Direction.DOWN)).id));
        script.put(5, () -> {
            ctl.press(0, 9);
            System.out.println("   passenger in car 0 presses 9");
        });
        for (int t = 0; t <= 14; t++) {
            Runnable r = script.get(t);
            if (r != null) r.run();
            ctl.tick();
            StringBuilder sb = new StringBuilder(String.format("t=%2d", t));
            for (Elevator e : ctl.cars())
                sb.append(String.format("  car%d floor %d %-9s", e.id, e.floor(), e.stateName()));
            System.out.println(sb);
        }
    }
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.TreeMap;

sealed interface Split permits EqualSplit, ExactSplit, PercentSplit {
    /** Returns each participant's share in paise; the shares always add up to the total. */
    Map<String, Long> shares(long total);
}

record EqualSplit(List<String> participants) implements Split {
    public Map<String, Long> shares(long total) {
        Map<String, Long> out = new LinkedHashMap<>();
        long base = total / participants.size();
        long remainder = total % participants.size();          // spread leftover paise one by one
        for (int i = 0; i < participants.size(); i++)
            out.put(participants.get(i), base + (i < remainder ? 1 : 0));
        return out;
    }
}

record ExactSplit(Map<String, Long> amounts) implements Split {
    public Map<String, Long> shares(long total) {
        long sum = amounts.values().stream().mapToLong(Long::longValue).sum();
        if (sum != total)
            throw new IllegalArgumentException("exact amounts sum " + sum + " != " + total);
        return amounts;
    }
}

record PercentSplit(Map<String, Integer> percents) implements Split {
    public Map<String, Long> shares(long total) {
        int sum = percents.values().stream().mapToInt(Integer::intValue).sum();
        if (sum != 100) throw new IllegalArgumentException("percentages sum " + sum + " != 100");
        Map<String, Long> out = new LinkedHashMap<>();
        long assigned = 0;
        String last = null;
        for (var e : percents.entrySet()) {
            long s = total * e.getValue() / 100;
            out.put(e.getKey(), s); assigned += s; last = e.getKey();
        }
        out.merge(last, total - assigned, Long::sum);          // residue to the last person
        return out;
    }
}
record Expense(String description, String payer, long total, Split split) {}
record Transfer(String from, String to, long amount) {}

class ExpenseManager {
    private final Map<String, Long> net = new TreeMap<>();                   // paid minus owed
    private final Map<String, Map<String, Long>> owes = new TreeMap<>();     // debtor, creditor

    synchronized void add(Expense e) {
        Map<String, Long> shares = e.split().shares(e.total());
        net.merge(e.payer(), e.total(), Long::sum);
        for (var s : shares.entrySet()) {
            net.merge(s.getKey(), -s.getValue(), Long::sum);
            if (!s.getKey().equals(e.payer()))
                owes.computeIfAbsent(s.getKey(), k -> new TreeMap<>())
                    .merge(e.payer(), s.getValue(), Long::sum);
        }
    }

    synchronized List<Transfer> pairwise() {
        List<Transfer> out = new ArrayList<>();
        owes.forEach((d, m) -> m.forEach((c, a) -> out.add(new Transfer(d, c, a))));
        return out;
    }

    /** Greedy minimum cash flow: the largest debtor pays the largest creditor. */
    synchronized List<Transfer> simplify() {
        PriorityQueue<Map.Entry<String, Long>> creditors = new PriorityQueue<>(
            Map.Entry.<String, Long>comparingByValue().reversed());
        PriorityQueue<Map.Entry<String, Long>> debtors = new PriorityQueue<>(
            Map.Entry.<String, Long>comparingByValue().reversed());
        net.forEach((u, v) -> {
            if (v > 0) creditors.add(new java.util.AbstractMap.SimpleEntry<>(u, v));
            if (v < 0) debtors.add(new java.util.AbstractMap.SimpleEntry<>(u, -v));
        });
        List<Transfer> out = new ArrayList<>();
        while (!creditors.isEmpty() && !debtors.isEmpty()) {
            var c = creditors.poll();
            var d = debtors.poll();
            long pay = Math.min(c.getValue(), d.getValue());
            out.add(new Transfer(d.getKey(), c.getKey(), pay));
            if (c.getValue() > pay) { c.setValue(c.getValue() - pay); creditors.add(c); }
            if (d.getValue() > pay) { d.setValue(d.getValue() - pay); debtors.add(d); }
        }
        return out;
    }
    synchronized Map<String, Long> net() { return new TreeMap<>(net); }
}
public class SplitwiseDemo {
    static String rs(long paise) { return String.format("Rs %d.%02d", paise / 100, paise % 100); }

    public static void main(String[] args) {
        ExpenseManager m = new ExpenseManager();
        List<String> all = List.of("Asha", "Bala", "Chitra", "Dev");
        m.add(new Expense("Dinner", "Asha", 100_000, new EqualSplit(all)));
        m.add(new Expense("Cab", "Bala", 40_001,
            new EqualSplit(List.of("Asha", "Bala", "Chitra"))));
        m.add(new Expense("Rent share", "Chitra", 90_000,
            new PercentSplit(new LinkedHashMap<>(Map.of("Chitra", 40, "Dev", 60)))));
        m.add(new Expense("Tickets", "Dev", 30_000,
            new ExactSplit(Map.of("Asha", 5_000L, "Bala", 10_000L, "Dev", 15_000L))));

        System.out.println("pairwise debts (debtor -> creditor):");
        for (Transfer t : m.pairwise())
            System.out.println("  " + t.from() + " -> " + t.to() + "  " + rs(t.amount()));
        System.out.println("net balances: " + m.net());
        System.out.println("simplified settlement:");
        for (Transfer t : m.simplify())
            System.out.println("  " + t.from() + " pays " + t.to() + "  " + rs(t.amount()));
        try {
            m.add(new Expense("Bad", "Asha", 1000,
                new PercentSplit(Map.of("Asha", 50, "Bala", 40))));
        } catch (IllegalArgumentException e) {
            System.out.println("rejected: " + e.getMessage());
        }
    }
}

