record Product(String code, String name, int price) {}

class Inventory {
    private final Map<String, Product> products = new HashMap<>();
    private final Map<String, Integer> stock = new HashMap<>();

    void load(Product p, int qty) {
        products.put(p.code(), p);
        stock.merge(p.code(), qty, Integer::sum);
    }
    Product find(String code) { return products.get(code); }
    boolean available(String code) { return stock.getOrDefault(code, 0) > 0; }
    void take(String code) {
        if (!available(code)) throw new IllegalStateException("sold out " + code);
        stock.merge(code, -1, Integer::sum);
    }
}

class ChangeMaker {
    private static final int[] DENOMS = {10, 5, 2, 1};            // rupee coins, largest first
    static List<Integer> change(int amount) {
        List<Integer> out = new ArrayList<>();
        for (int d : DENOMS) while (amount >= d) { out.add(d); amount -= d; }
        return out;
    }
}
interface VendingState {
    default void insertCoin(VendingMachine m, int coin) { deny("insertCoin"); }
    default void select(VendingMachine m, String code) { deny("select"); }
    default void cancel(VendingMachine m) { deny("cancel"); }
    String name();
    private void deny(String op) {
        throw new IllegalStateException(op + " not allowed in state " + name());
    }
}

class IdleState implements VendingState {
    public String name() { return "IDLE"; }
    public void insertCoin(VendingMachine m, int coin) {
        m.addCredit(coin);
        m.setState(new HasMoneyState());
    }
}

class HasMoneyState implements VendingState {
    public String name() { return "HAS_MONEY"; }
    public void insertCoin(VendingMachine m, int coin) { m.addCredit(coin); }
    public void select(VendingMachine m, String code) {
        Product p = m.inventory().find(code);
        if (p == null || !m.inventory().available(code)) {
            System.out.println("  '" + code + "' unavailable, credit kept: " + m.credit());
            return;
        }
        if (m.credit() < p.price()) {
            System.out.println("  need Rs " + (p.price() - m.credit()) + " more for " + p.name());
            return;
        }
        m.setState(new DispensingState());
        m.dispense(p);                                   // Dispensing state completes the sale
    }
    public void cancel(VendingMachine m) {
        System.out.println("  refund " + ChangeMaker.change(m.credit()));
        m.clearCredit();
        m.setState(new IdleState());
    }
}

class DispensingState implements VendingState {
    public String name() { return "DISPENSING"; }        // all user actions are denied by default
}
class VendingMachine {
    private final Inventory inventory = new Inventory();
    private VendingState state = new IdleState();
    private int credit;

    Inventory inventory() { return inventory; }
    int credit() { return credit; }
    void addCredit(int c) { credit += c; }
    void clearCredit() { credit = 0; }
    void setState(VendingState s) { state = s; }
    String stateName() { return state.name(); }

    synchronized void insertCoin(int coin) { state.insertCoin(this, coin); }
    synchronized void select(String code) { state.select(this, code); }
    synchronized void cancel() { state.cancel(this); }

    void dispense(Product p) {                           // called while in DISPENSING
        inventory.take(p.code());
        int change = credit - p.price();
        System.out.println("  dispensed " + p.name() + ", change " + ChangeMaker.change(change));
        clearCredit();
        setState(new IdleState());
    }
}
