import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.LongSupplier;

interface RateLimiter {
    boolean tryAcquire(String key);
}

record Limit(int capacity, double refillPerSecond) {
    Limit {
        if (capacity <= 0 || refillPerSecond < 0) throw new IllegalArgumentException("limit");
    }
}
final class TokenBucket {
    private record State(double tokens, long lastNanos) {}

    private final Limit limit;
    private final LongSupplier nanoClock;
    private final AtomicReference<State> state;

    TokenBucket(Limit limit, LongSupplier nanoClock) {
        this.limit = limit;
        this.nanoClock = nanoClock;
        this.state = new AtomicReference<>(new State(limit.capacity(), nanoClock.getAsLong()));
    }

    boolean tryAcquire() {
        while (true) {                                    // lock-free compare-and-set loop
            State s = state.get();
            long now = nanoClock.getAsLong();
            double refilled = Math.min(limit.capacity(),
                s.tokens() + (now - s.lastNanos()) / 1e9 * limit.refillPerSecond());
            if (refilled < 1.0) {
                // persist the fractional refill so that elapsed time is not lost
                if (state.compareAndSet(s, new State(refilled, now))) return false;
            } else if (state.compareAndSet(s, new State(refilled - 1.0, now))) {
                return true;
            }
        }
    }
}
class TokenBucketRateLimiter implements RateLimiter {
    private final Limit limit;
    private final LongSupplier clock;
    private final Map<String, TokenBucket> buckets = new ConcurrentHashMap<>();

    TokenBucketRateLimiter(Limit limit, LongSupplier clock) {
        this.limit = limit;
        this.clock = clock;
    }

    public boolean tryAcquire(String key) {
        return buckets.computeIfAbsent(key, k -> new TokenBucket(limit, clock)).tryAcquire();
    }
    int trackedKeys() { return buckets.size(); }
}

/** Alternative policy behind the same interface: exact, but O(limit) memory per key. */
class SlidingWindowLogRateLimiter implements RateLimiter {
    private final int maxRequests;
    private final long windowNanos;
    private final LongSupplier clock;
    private final Map<String, Deque<Long>> logs = new ConcurrentHashMap<>();

    SlidingWindowLogRateLimiter(int maxRequests, long windowMillis, LongSupplier clock) {
        this.maxRequests = maxRequests;
        this.windowNanos = windowMillis * 1_000_000L;
        this.clock = clock;
    }
    public boolean tryAcquire(String key) {
        Deque<Long> log = logs.computeIfAbsent(key, k -> new ArrayDeque<>());
        synchronized (log) {
            long now = clock.getAsLong();
            while (!log.isEmpty() && now - log.peekFirst() >= windowNanos) log.pollFirst();
            if (log.size() >= maxRequests) return false;
            log.addLast(now);
            return true;
        }
    }
}
public class RateLimiterDemo {
    static long[] now = {0L};                                    // fake clock in nanoseconds
    static void advanceMillis(long ms) { now[0] += ms * 1_000_000L; }

    static String burst(RateLimiter rl, String key, int n) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) sb.append(rl.tryAcquire(key) ? 'A' : 'x');
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        RateLimiter tb = new TokenBucketRateLimiter(new Limit(5, 2.0), () -> now[0]);
        System.out.println("token bucket (capacity 5, 2 tokens/s), A = allowed, x = rejected");
        System.out.println("  t=0.0s burst of 7 for alice : " + burst(tb, "alice", 7));
        System.out.println("  t=0.0s burst of 3 for bob   : " + burst(tb, "bob", 3));
        advanceMillis(1000);
        System.out.println("  t=1.0s burst of 4 for alice : " + burst(tb, "alice", 4));
        advanceMillis(10_000);
        System.out.println("  t=11s  burst of 7 for alice : " + burst(tb, "alice", 7));

        now[0] = 0;
        RateLimiter sw = new SlidingWindowLogRateLimiter(3, 1000, () -> now[0]);
        System.out.println("sliding window log (3 per 1000 ms)");
        System.out.println("  t=0     : " + burst(sw, "carol", 4));
        advanceMillis(600);
        System.out.println("  t=0.6s  : " + burst(sw, "carol", 1));
        advanceMillis(500);
        System.out.println("  t=1.1s  : " + burst(sw, "carol", 4));

        TokenBucketRateLimiter shared = new TokenBucketRateLimiter(new Limit(100, 0.0), () -> 0L);
        AtomicInteger allowed = new AtomicInteger();
        ExecutorService pool = Executors.newFixedThreadPool(8);
        for (int t = 0; t < 8; t++)
            pool.submit(() -> {
                for (int i = 0; i < 1000; i++)
                    if (shared.tryAcquire("hot")) allowed.incrementAndGet();
            });
        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);
        System.out.println("8 threads x 1000 calls, capacity 100, no refill: allowed = " + allowed);
    }
}

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeSet;
import java.util.UUID;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.ReentrantLock;
import java.util.function.Supplier;

enum SeatStatus { AVAILABLE, HELD, BOOKED }

record Hold(String id, String showId, String userId, List<String> seats, Instant expiresAt) {}

class SeatUnavailableException extends RuntimeException {
    SeatUnavailableException(String m) { super(m); }
}

class HoldExpiredException extends RuntimeException {
    HoldExpiredException(String m) { super(m); }
}
class Show {
    private static final Duration HOLD_TTL = Duration.ofMinutes(5);

    private final String id;
    private final Supplier<Instant> clock;
    private final ReentrantLock lock = new ReentrantLock();           // one lock per show
    private final Map<String, SeatStatus> status = new HashMap<>();
    private final Map<String, Hold> holdBySeat = new HashMap<>();
    private final Map<String, Hold> holds = new HashMap<>();

    Show(String id, List<String> seatIds, Supplier<Instant> clock) {
        this.id = id; this.clock = clock;
        seatIds.forEach(s -> status.put(s, SeatStatus.AVAILABLE));
    }

    /** All-or-nothing: either every requested seat is held, or none is. */
    Hold hold(String userId, List<String> seats) {
        lock.lock();
        try {
            expireStale();                                              // lazy expiry on every call
            for (String s : new TreeSet<>(seats))
                if (status.get(s) != SeatStatus.AVAILABLE)
                    throw new SeatUnavailableException("seat " + s + " is " + status.get(s));
            Hold h = new Hold(UUID.randomUUID().toString().substring(0, 6), id, userId,
                              List.copyOf(seats), clock.get().plus(HOLD_TTL));
            for (String s : seats) { status.put(s, SeatStatus.HELD); holdBySeat.put(s, h); }
            holds.put(h.id(), h);
            return h;
        } finally { lock.unlock(); }
    }

    void confirm(String holdId) {                           // called after payment succeeds
        lock.lock();
        try {
            expireStale();
            Hold h = holds.remove(holdId);
            if (h == null) throw new HoldExpiredException("hold " + holdId + " expired or unknown");
            for (String s : h.seats()) { status.put(s, SeatStatus.BOOKED); holdBySeat.remove(s); }
        } finally { lock.unlock(); }
    }

    void release(String holdId) {                           // payment failed or user left
        lock.lock();
        try {
            Hold h = holds.remove(holdId);
            if (h == null) return;
            for (String s : h.seats()) {
                status.put(s, SeatStatus.AVAILABLE);
                holdBySeat.remove(s);
            }
        } finally { lock.unlock(); }
    }

    private void expireStale() {                                        // caller holds the lock
        Instant now = clock.get();
        List<String> dead = new ArrayList<>();
        for (Hold h : holds.values()) if (!h.expiresAt().isAfter(now)) dead.add(h.id());
        for (String hid : dead) release(hid);               // reentrant: lock already held
    }

    Map<SeatStatus, Long> summary() {
        lock.lock();
        try {
            expireStale();
            Map<SeatStatus, Long> m = new java.util.EnumMap<>(SeatStatus.class);
            status.values().forEach(v -> m.merge(v, 1L, Long::sum));
            return m;
        } finally { lock.unlock(); }
    }
}
class NaiveShow {                                          // BROKEN on purpose: check-then-act race
    private final Map<String, String> owner = new java.util.concurrent.ConcurrentHashMap<>();

    boolean book(String seat, String user) {
        if (owner.containsKey(seat)) return false;         // check
        try {
            Thread.sleep(1);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        owner.put(seat, user);                             // act: others may have passed the check
        return true;
    }
}
public class BookingDemo {
    public static void main(String[] args) throws Exception {
        Instant[] now = {Instant.parse("2026-03-01T18:00:00Z")};
        Show show = new Show("S1", List.of("A1", "A2", "A3", "A4"), () -> now[0]);

        Hold alice = show.hold("alice", List.of("A1", "A2"));
        System.out.println("alice holds " + alice.seats() + " until " + alice.expiresAt());
        try { show.hold("bob", List.of("A2", "A3")); } catch (SeatUnavailableException e) {
            System.out.println("bob rejected: " + e.getMessage() + " (A3 stays free)");
        }
        show.confirm(alice.id());
        System.out.println("after alice confirms: " + show.summary());

        Hold bob = show.hold("bob", List.of("A3"));
        now[0] = now[0].plus(Duration.ofMinutes(6));                    // bob never pays
        System.out.println("after 6 minutes: " + show.summary());
        try { show.confirm(bob.id()); } catch (HoldExpiredException e) {
            System.out.println("late payment rejected: expired hold");
        }

        // race 1: naive check-then-act
        NaiveShow naive = new NaiveShow();
        AtomicInteger naiveWins = new AtomicInteger();
        race(20, i -> { if (naive.book("A1", "u" + i)) naiveWins.incrementAndGet(); });
        System.out.println("naive:  20 users race for one seat, winners = " + naiveWins);

        // race 2: locked hold
        Show safe = new Show("S2", List.of("A1"), Instant::now);
        AtomicInteger safeWins = new AtomicInteger();
        race(20, i -> {
            try { safe.hold("u" + i, List.of("A1")); safeWins.incrementAndGet(); }
            catch (SeatUnavailableException ignored) { }
        });
        System.out.println("locked: 20 users race for one seat, winners = " + safeWins);
    }

    static void race(int threads, java.util.function.IntConsumer task) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CountDownLatch go = new CountDownLatch(1);
        for (int i = 0; i < threads; i++) {
            final int n = i;
            pool.submit(() -> {
                try { go.await(); } catch (InterruptedException e) { return; }
                task.accept(n);
            });
        }
        go.countDown();
        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);
    }
}
